import { test, expect } from '@playwright/test';

test.describe('Payment Processing Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display loading state while payment is processing', async ({ page }) => {
    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /payment/i });
    await expect(paymentForm).toBeVisible();

    // Fill in card number using getByLabel
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('411111111111111');

    // Fill in expiry date using getByLabel
    const expiryInput = page.getByLabel(/expiry date/i);
    await expiryInput.fill('12/25');

    // Fill in CVV using getByLabel
    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Click process payment button using getByRole
    const processButton = page.getByRole('button', { name: /process payment/i });
    await processButton.click();

    // Verify loading spinner appears
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify loading text is displayed
    const loadingText = page.getByText(/processing payment/i);
    await expect(loadingText).toBeVisible();

    // Verify payment button is disabled during processing
    await expect(processButton).toBeDisabled();

    // Wait for payment to complete
    await page.waitForTimeout(2000);

    // Verify loading state is removed
    await expect(loadingSpinner).not.toBeVisible();
    await expect(loadingText).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle payment processing timeout and display error state', async ({ page }) => {
    // Fill in card number using getByLabel
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('411111111111111');

    // Fill in expiry date using getByLabel
    const expiryInput = page.getByLabel(/expiry date/i);
    await expiryInput.fill('12/25');

    // Fill in CVV using getByLabel
    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Click process payment button using getByRole
    const processButton = page.getByRole('button', { name: /process payment/i });
    await processButton.click();

    // Verify loading spinner appears
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for timeout
    await page.waitForTimeout(5000);

    // Verify loading state is removed
    await expect(loadingSpinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details are shown
    const errorDetails = page.getByText(/please try again/i);
    await expect(errorDetails).toBeVisible();

    // Verify payment button is re-enabled
    await expect(processButton).not.toBeDisabled();
  });
});
